<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>API Docs</title><style>body{background:#0d0b0a;color:#eee;font:15px Arial;margin:0}.wrap{max-width:1000px;margin:auto;padding:30px}code{background:#211711;color:#ffad54;padding:4px 8px;border-radius:7px}.ep{padding:16px;margin:12px 0;background:#181310;border:1px solid #3a2b22;border-radius:14px}.muted{color:#baa99d}</style></head><body><div class="wrap"><h1>Ady_vandorez REST API</h1><p class="muted">Base URL: <code><?= html_escape($base) ?></code>. Endpoint privat memakai header <code>Authorization: Bearer TOKEN</code>.</p><?php $eps=[['GET','/health','Status API'],['GET','/config','Konfigurasi aplikasi dan metode pembayaran'],['POST','/auth/register','Registrasi pelanggan'],['POST','/auth/login','Login pelanggan'],['POST','/auth/logout','Logout'],['POST','/auth/forgot-password','Permintaan reset password'],['GET','/designs','Katalog desain'],['GET','/designs/{id}','Detail dan harga desain'],['GET','/profile','Profil pelanggan'],['PUT','/profile','Ubah profil'],['GET','/orders','Riwayat pesanan'],['POST','/orders','Membuat pesanan'],['GET','/orders/{id}','Detail pesanan'],['PUT','/orders/{id}','Ubah pesanan berstatus MASUK'],['POST','/orders/{id}/files','Upload referensi multipart field file'],['POST','/orders/{id}/revisions','Ajukan revisi'],['GET','/payments/methods','Metode pembayaran'],['POST','/orders/{id}/payment-confirmations','Upload bukti, multipart field proof'],['GET','/payment-confirmations','Riwayat konfirmasi pembayaran'],['GET','/notifications','Notifikasi'],['PUT','/notifications/{id}/read','Tandai dibaca']];foreach($eps as $e):?><div class="ep"><b><?= $e[0] ?></b> <code><?= $e[1] ?></code><div class="muted"><?= $e[2] ?></div></div><?php endforeach;?></div></body></html>